/* Compact excerpts keep the desktop grid even; the complete copy opens separately. */
.activity-grid.is-compact{grid-auto-rows:1fr;align-items:stretch}
.activity-grid.is-compact .activity-card-actions{display:grid;gap:8px;margin-top:auto;padding-top:2px}
.activities .activity-grid.is-compact .activity-more{min-height:44px;width:auto;justify-self:start;padding:6px 0;margin:0;background:none;border:0;box-shadow:none;color:var(--hp-ink);font:700 1rem/1.3 Jost,sans-serif;text-decoration:underline;text-underline-offset:4px;border-radius:4px}
.activities .activity-grid.is-compact .activity-card-actions>button:last-child{margin:0}
#activity-detail{box-sizing:border-box;width:min(660px,calc(100% - 32px));max-height:calc(100dvh - 32px);overflow:auto;padding:24px;border:3px solid var(--hp-ink);border-radius:24px;background:linear-gradient(135deg,var(--hp-mint),var(--hp-cyan));color:var(--hp-ink);box-shadow:8px 8px 0 var(--hp-purple)}
#activity-detail::backdrop{background:rgba(7,15,43,.8)}
#activity-detail .activity-detail-close{display:block;margin:0 0 16px auto;padding:10px 18px;min-height:44px;background:var(--hp-ink);color:var(--hp-orange);border:2px solid var(--hp-ink);border-radius:999px;font:700 1rem/1.3 Jost,sans-serif}
#activity-detail h3{margin:0 0 20px;font:700 clamp(1.7rem,4vw,2.3rem)/1.2 Jost,sans-serif;color:var(--hp-ink)}
#activity-detail p{margin:0 0 18px;font:400 1.125rem/1.5 Jost,sans-serif;color:var(--hp-ink)}
#activity-detail .activity-detail-go{display:flex;align-items:center;justify-content:center;box-sizing:border-box;min-height:48px;padding:12px 20px;border:2px solid var(--hp-ink);border-radius:999px;background:var(--hp-orange);color:var(--hp-ink);font:700 1.05rem/1.3 Jost,sans-serif;text-decoration:none;text-align:center}
@media(max-width:560px){.activity-grid.is-compact{grid-auto-rows:auto}.activity-grid.is-compact .activity-card-actions{margin-top:0}}
</style>

