/* Align labels within each visible row; cards and paragraphs keep their natural height.
   Recalculate after fonts, resizing and filters; rows never borrow height from other rows. */
(function(){
  var grid=document.querySelector('.activity-grid');
  if(!grid) return;
  var pending=false, lastWidth=-1;
  function alignSlots(){
    pending=false;
    var cards=Array.from(grid.querySelectorAll('article')).filter(function(card){return !card.hidden;});
    cards.forEach(function(card){
      card.querySelectorAll('.tag,h3,p,button').forEach(function(slot){slot.style.minHeight='';});
    });
    if(getComputedStyle(grid).gridTemplateColumns.trim().split(/\s+/).length===1) return;
    var rows=new Map();
    cards.forEach(function(card){
      var top=card.offsetTop;
      if(!rows.has(top)) rows.set(top,[]);
      rows.get(top).push(card);
    });
    rows.forEach(function(row){
      ['.tag','h3'].forEach(function(selector){
        var slots=row.map(function(card){return card.querySelector(selector);}).filter(Boolean);
        var height=Math.ceil(Math.max(0,...slots.map(function(slot){return slot.getBoundingClientRect().height;})));
        slots.forEach(function(slot){slot.style.minHeight=height+'px';});
      });
    });
  }
  function schedule(){if(!pending){pending=true;requestAnimationFrame(alignSlots);}}
  window.addEventListener('resize',schedule);
  if(document.fonts) document.fonts.ready.then(schedule);
  if(window.ResizeObserver) new ResizeObserver(function(entries){
    var width=entries[0].contentRect.width;
    if(width!==lastWidth){lastWidth=width;schedule();}
  }).observe(grid);
  new MutationObserver(schedule).observe(grid,{subtree:true,attributes:true,attributeFilter:['hidden']});
  schedule();
})();

