/* Give each activity a useful excerpt and a native full-description dialog.
   Keep complete original copy available; equalise only labels/buttons, never paragraphs. */
(function(){
  var grid=document.querySelector('.activity-grid');
  if(!grid||typeof HTMLDialogElement==='undefined') return;
  var dialog=document.createElement('dialog');
  dialog.id='activity-detail';
  dialog.setAttribute('aria-labelledby','activity-detail-title');
  dialog.innerHTML='<button type="button" class="activity-detail-close">Close ×</button><h3 id="activity-detail-title"></h3><div class="activity-detail-copy"></div><a class="activity-detail-go"></a>';
  document.body.appendChild(dialog);
  var opener=null;
  dialog.querySelector('.activity-detail-close').addEventListener('click',function(){dialog.close();});
  dialog.addEventListener('close',function(){if(opener&&!opener.closest('[hidden]'))opener.focus();});
  Array.from(grid.children).forEach(function(card){
    var body=card.querySelector('div'), paragraphs=Array.from(body.querySelectorAll(':scope>p'));
    var primary=body.querySelector('button'), title=card.querySelector('h3').textContent;
    var summary=document.createElement('p');summary.className='activity-summary';summary.textContent=card.dataset.summary;
    var full=document.createElement('template');full.className='activity-full-copy';
    paragraphs.forEach(function(p){full.content.appendChild(p);});
    var more=document.createElement('button');more.type='button';more.className='activity-more';more.textContent='Read more';more.setAttribute('aria-label','Read more about '+title);more.setAttribute('aria-haspopup','dialog');
    var actions=document.createElement('div');actions.className='activity-card-actions';
    body.appendChild(summary);body.appendChild(full);actions.appendChild(more);actions.appendChild(primary);body.appendChild(actions);
    more.addEventListener('click',function(){
      opener=more;
      dialog.querySelector('h3').textContent=title;
      dialog.querySelector('.activity-detail-copy').replaceChildren(full.content.cloneNode(true));
      var link=dialog.querySelector('a'), route=primary.getAttribute('onclick').match(/location.href=['"]([^'"]+)/);
      link.textContent=primary.textContent;link.href=route?route[1]:'#activities';
      dialog.showModal();
    });
  });
  grid.classList.add('is-compact');
  var pending=false,lastWidth=-1;
  function alignSlots(){
    pending=false;
    var cards=Array.from(grid.children).filter(function(card){return !card.hidden;});
    cards.forEach(function(card){card.querySelectorAll('.tag,h3,button').forEach(function(slot){slot.style.minHeight='';});});
    if(getComputedStyle(grid).gridTemplateColumns.trim().split(/\s+/).length===1)return;
    ['.tag','h3','.activity-card-actions>button:last-child'].forEach(function(selector){
      var slots=cards.map(function(card){return card.querySelector(selector);});
      var height=Math.ceil(Math.max(0,...slots.map(function(slot){return slot.getBoundingClientRect().height;})));
      slots.forEach(function(slot){slot.style.minHeight=height+'px';});
    });
  }
  function schedule(){if(!pending){pending=true;requestAnimationFrame(alignSlots);}}
  window.addEventListener('resize',schedule);
  if(document.fonts)document.fonts.ready.then(schedule);
  if(window.ResizeObserver)new ResizeObserver(function(entries){var width=entries[0].contentRect.width;if(width!==lastWidth){lastWidth=width;schedule();}}).observe(grid);
  new MutationObserver(schedule).observe(grid,{subtree:true,attributes:true,attributeFilter:['hidden']});
  schedule();
})();
